<div class="data-table customers"><div class="tr th"><span>Customer</span><span>Account</span><span>Balance</span><span>Status</span><span></span></div><?php foreach($customers as $c):?><div class="tr"><span class="name"><i><?=initials($c['first_name'].' '.$c['last_name'])?></i><b><?=html_escape($c['first_name'].' '.$c['last_name'])?><small><?=html_escape($c['email'])?></small></b></span><span><?=$c['account_count']?> account<?=$c['account_count']==1?'':'s'?></span><strong><?=money($c['total_balance'])?></strong><span class="<?=status_class($c['status'])?>"><?=ucfirst($c['status'])?></span><a href="<?=site_url('admin/customers/'.$c['id'])?>">›</a></div><?php endforeach?></div>
